(()=>{document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("a.footnote-backref").forEach(function(o){o.addEventListener("click",function(n){console.log("test");let e=this.getAttribute("href").replace("#",""),t=document.getElementById(e);if(t){n.preventDefault();let i=t.getBoundingClientRect().top+window.scrollY-window.innerHeight/5+t.offsetHeight/5;window.scrollTo({top:i,behavior:"smooth"}),history.pushState(null,"","#"+e)}})})});})();
